<?php
declare(strict_types=1);require __DIR__.'/_lib.php';
function loadv():array{return cti_store_load('vendors.json',['schema'=>'cti.vendors.v3','updatedAt'=>gmdate('c'),'vendors'=>[]]);}
function vnorm(array $x,?array $o=null):array{$name=cti_clean_scalar($x['name']??$o['name']??null,180);$slug=cti_clean_scalar($x['slug']??$o['slug']??null,180);if(!$name||!$slug||!preg_match('/^[a-z0-9-]+$/',$slug))cti_json(422,['ok'=>false,'error'=>'invalid_vendor']);$st=cti_clean_scalar($x['status']??$o['status']??'draft',20);if(!in_array($st,['draft','published','unpublished','archived'],true))cti_json(422,['ok'=>false,'error'=>'invalid_status']);return['id'=>$o['id']??cti_clean_scalar($x['id']??null,100)??'vendor:'.bin2hex(random_bytes(8)),'name'=>$name,'slug'=>$slug,'category'=>cti_clean_scalar($x['category']??$o['category']??null,120),'segment'=>cti_clean_scalar($x['segment']??$o['segment']??null,120),'website'=>cti_clean_scalar($x['website']??$o['website']??null,500),'summary'=>cti_clean_scalar($x['summary']??$o['summary']??null,2000),'body'=>cti_clean_scalar($x['body']??$o['body']??null,30000),'priority'=>cti_bool($x['priority']??$o['priority']??false),'buyingTriggers'=>$x['buyingTriggers']??$o['buyingTriggers']??[],'activationPlays'=>$x['activationPlays']??$o['activationPlays']??[],'status'=>$st,'publishedAt'=>$st==='published'?($o['publishedAt']??gmdate('c')):null,'updatedAt'=>gmdate('c')];}
$m=$_SERVER['REQUEST_METHOD']??'GET';$s=loadv();if($m==='GET'){$admin=($_GET['admin']??'')==='1';if($admin)cti_auth();$slug=cti_clean_scalar($_GET['slug']??null,180);$v=array_values(array_filter($s['vendors'],fn($x)=>($admin||($x['status']??'')==='published')&&(!$slug||($x['slug']??'')===$slug)));cti_json(200,['ok'=>true,'schema'=>'cti.vendors.v3','count'=>count($v),'vendors'=>$v]);}
cti_auth();cti_rate_limit('vendor-write',60,60);$in=cti_read_json();$id=cti_clean_scalar($in['id']??null,100);$idx=null;foreach($s['vendors'] as $k=>$v)if(($id&&($v['id']??'')===$id)||(isset($in['slug'])&&($v['slug']??'')===$in['slug']){$idx=$k;break;}
if($m==='DELETE'){cti_auth(['admin']);if($idx===null)cti_json(404,['ok'=>false,'error'=>'not_found']);$s['vendors'][$idx]['status']='archived';$s['vendors'][$idx]['updatedAt']=gmdate('c');cti_atomic_store('vendors.json',$s);cti_audit('vendors',['action'=>'archive','id'=>$s['vendors'][$idx]['id']]);cti_json(200,['ok'=>true,'vendor'=>$s['vendors'][$idx]]);}
if(!in_array($m,['POST','PUT','PATCH'],true))cti_json(405,['ok'=>false,'error'=>'method_not_allowed']);$old=$idx!==null?$s['vendors'][$idx]:null;$v=vnorm($in,$old);if($idx===null)$s['vendors'][]=$v;else$s['vendors'][$idx]=$v;$s['updatedAt']=gmdate('c');cti_atomic_store('vendors.json',$s);cti_audit('vendors',['action'=>$old?'update':'create','id'=>$v['id'],'status'=>$v['status']]);cti_json($old?200:201,['ok'=>true,'vendor'=>$v]);